import { z } from "astro/zod";
//#region src/schemas/logo.ts
const LogoConfigSchema = () => z.union([z.object({
	src: z.string(),
	alt: z.string().default(""),
	replacesTitle: z.boolean().default(false)
}), z.object({
	dark: z.string(),
	light: z.string(),
	alt: z.string().default(""),
	replacesTitle: z.boolean().default(false)
})]).optional();
//#endregion
export { LogoConfigSchema };
